html:
{{ get_solua_print_css() }}{% set p = get_pick_list_print_data(doc) %}
<h2>Pick List / 拣货单（简版）</h2>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — Documento não oficial / 非正式凭证</div>{% endif %}
<table class="meta"><tr><td><b>Cliente / 客户: {{ (p.customer or '—') | e }}</b><br>N.º / 单号: {{ doc.name | e }}</td><td>Data / 日期: {{ (doc.get('creation') | string)[:10] if doc.get('creation') else '' }}<br>Uso / 用途: {{ (p.purpose or '—') | e }}<br>Origem / 来源: {{ (p.source or '—') | e }}</td></tr></table>
{% if doc.get('custom_print_additional_notes', 1) and doc.get('custom_additional_notes') %}<div class="block">补充说明 / Observações: {{ doc.get('custom_additional_notes') | e }}</div>{% endif %}
<table class="items"><thead><tr><th class="col-idx">#</th><th class="col-spu">SPU</th><th>SKU / 货号</th><th>补充说明 / Observações</th><th class="col-qty">Quantidade / 数量</th></tr></thead><tbody>
{% for item in p['items'] %}<tr><td class="col-idx">{{ loop.index }}</td><td class="col-spu">{{ (item.spu or item.template_code or item.item_code) | e }}</td><td>{{ item.item_code | e }}</td><td>{{ (item.additional_notes or '—') | e }}</td><td class="col-qty num">{% if item.pack_uom %}<b>{{ item.pack_uom | e }}</b><br><small>(= {{ format_print_qty(item.qty) }}{% if item.uom %} {{ item.uom | e }}{% endif %})</small>{% else %}{{ format_print_qty(item.qty) }}{% if item.uom %} {{ item.uom | e }}{% endif %}{% endif %}</td></tr>{% endfor %}
</tbody><tfoot><tr><td class="num" colspan="4"><b>Total Qty / 总数量</b></td><td class="col-qty num"><b>{{ format_print_qty(p.total_qty) }}{% if p.total_uom %} {{ p.total_uom | e }}{% endif %}</b></td></tr></tfoot></table>
<table class="confirm"><thead><tr><th>Separação / 拣货确认</th><th>Carregamento / 装车确认（司机）</th></tr></thead><tbody><tr><td><div class="line">Separado por / 拣货人: ________________________</div><div class="line">Assinatura / 签名: ________________________</div><div class="line">Data / 日期: ____________　Hora / 时间: ____________</div></td><td><div class="line">Volumes / 件数(箱): __________　Conferido / 核对数量: __________</div><div class="line">Motorista / 司机: ________________________</div><div class="line">Assinatura / 签名: ________________________</div><div class="line">Data / 日期: ____________　Hora / 时间: ____________</div></td></tr></tbody></table>
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>
